import os
import random
import string
from typing import List

# Data type: filesystem path
# We generate a bytes buffer that the fuzzing harness will split into
# FUZZ_PARAM_FILENAME and FUZZ_PARAM_STR (and possibly additional integers).
# Typical fuzzers use simple separators; here we embed multiple plausible
# filename/path segments and general strings so both consumers get valid, diverse inputs.

SEPS = ['/', '\\']
HOME_MARKERS = ['~', '~user']
ENV_MARKERS = ['%USERPROFILE%', '%APPDATA%', '%TEMP%', '$HOME', '${HOME}', '$TMPDIR']
COMMON_DIRS_UNIX = [
    '/', '/tmp', '/var', '/var/tmp', '/usr', '/usr/local', '/etc', '/home', '/opt', '/dev/null',
]
COMMON_DIRS_WIN = [
    'C:\\', 'C:\\Temp', 'C:\\Windows', 'C:\\Users\\Public', 'D:\\Data',
]
REL_PARTS = ['.', '..', '...', '.', '..', '.hidden', '..\\..', '../..']
FILENAMES = [
    'README', 'file', 'data', 'notes', 'config', 'Makefile', '.gitignore',
    'a.txt', 'b.bin', 'cinder.txt', 'colors.svg', 'image.png', 'archive.tar.gz',
]
EXTS = ['', '.txt', '.bin', '.dat', '.log', '.cfg', '.json', '.xml']
SEARCH_NAMES = [
    'build', 'src', 'include', 'assets', 'bin', 'obj', 'out', '.git',
    'CMakeLists.txt', 'LICENSE', 'README.md', 'package.json', 'Cargo.toml',
]

def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(len(items))]

def _rand_token(rng: random.Random) -> str:
    # Produce a general-purpose token for path or general string
    alph = string.ascii_letters + string.digits + '._-+'
    n = rng.randint(1, 16)
    return ''.join(rng.choice(alph) for _ in range(n))

def _make_filename(rng: random.Random) -> str:
    # Generate a path-like string that is likely valid on either POSIX or Windows
    parts: List[str] = []

    # Possibly start with special expansions or roots
    start_kind = rng.random()
    if start_kind < 0.15:
        parts.append(_rand_choice(rng, HOME_MARKERS))
    elif start_kind < 0.30:
        parts.append(_rand_choice(rng, ENV_MARKERS))
    elif start_kind < 0.55:
        parts.append(_rand_choice(rng, COMMON_DIRS_UNIX))
    elif start_kind < 0.80:
        parts.append(_rand_choice(rng, COMMON_DIRS_WIN))
    elif start_kind < 0.90:
        # Relative start
        parts.append(_rand_choice(rng, REL_PARTS))
    else:
        parts.append('')  # possibly empty to allow relative paths like 'foo/bar'

    # Number of additional segments
    segs = rng.randint(1, 6)
    for _ in range(segs):
        chooser = rng.random()
        if chooser < 0.10:
            parts.append(_rand_choice(rng, REL_PARTS))
        elif chooser < 0.20:
            parts.append('')  # may cause duplicate separators
        elif chooser < 0.30:
            parts.append('.' + _rand_token(rng))  # hidden file/dir
        elif chooser < 0.45:
            parts.append(_rand_choice(rng, SEARCH_NAMES))
        elif chooser < 0.70:
            base = _rand_choice(rng, FILENAMES)
            ext = _rand_choice(rng, EXTS)
            parts.append(base + ext)
        else:
            parts.append(_rand_token(rng))

    # Randomly mix separators
    sep = _rand_choice(rng, SEPS)
    path = sep.join(filter(lambda s: s is not None, parts))

    # Occasionally add trailing separator
    if rng.random() < 0.25:
        path += _rand_choice(rng, SEPS)

    # Occasionally insert repeated separators to exercise expandPath collapsing
    if rng.random() < 0.3:
        path = path.replace('/', '///')
    if rng.random() < 0.3:
        path = path.replace('\\', '\\\\\\\\')

    return path

def _make_search_string(rng: random.Random) -> str:
    # This string is used by findAncestorDir/File as a relative search path.
    # Generate both single names and multi-segment relatives.
    kind = rng.random()
    if kind < 0.25:
        return _rand_choice(rng, SEARCH_NAMES)
    elif kind < 0.50:
        return _rand_choice(rng, FILENAMES) + _rand_choice(rng, EXTS)
    elif kind < 0.70:
        # Nested relative path
        segs = rng.randint(1, 3)
        seglist = []
        for _ in range(segs):
            if rng.random() < 0.2:
                seglist.append('..')
            else:
                seglist.append(_rand_choice(rng, SEARCH_NAMES + FILENAMES))
        return '/'.join(seglist)
    elif kind < 0.85:
        # Hidden directories/files
        return '.' + _rand_choice(rng, SEARCH_NAMES + FILENAMES)
    else:
        # Token with separators mixed
        raw = _rand_token(rng)
        if rng.random() < 0.5:
            raw += _rand_choice(rng, EXTS)
        return raw

def _assemble_buffer(fields: List[bytes]) -> bytes:
    # Simple TLV-like framing: each field prefixed by 2-byte big-endian length
    # This avoids ambiguity when FUZZ_PARAM_* read chunks.
    out = bytearray()
    for f in fields:
        if len(f) > 4095:
            f = f[:4095]
        out += len(f).to_bytes(2, 'big')
        out += f
    return bytes(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Produce multiple candidate filenames to give the harness room if it
    # consumes more than one FUZZ_PARAM_FILENAME across different stubs.
    filenames: List[str] = []
    for _ in range(3):
        filenames.append(_make_filename(rng))

    # Produce multiple search strings for FUZZ_PARAM_STR
    search_strings: List[str] = []
    for _ in range(3):
        search_strings.append(_make_search_string(rng))

    # Include some ASCII content for writeString payloads; keep under limit
    # and include varied line endings and unicode-like bytes.
    payload_lines = []
    line_count = rng.randint(3, 20)
    for i in range(line_count):
        line = []
        # header-like, key-value, and random content
        if rng.random() < 0.3:
            line.append(f"key{i}=")
            line.append(_rand_token(rng))
        elif rng.random() < 0.6:
            line.append(_rand_choice(rng, ["INFO", "WARN", "ERROR", "DEBUG"]))
            line.append(": ")
            line.append(_rand_token(rng))
        else:
            line.append(_rand_token(rng))
        if rng.random() < 0.3:
            line.append(_rand_choice(rng, [" ", "\t"]))
            line.append(_rand_choice(rng, SEARCH_NAMES + FILENAMES))
        if rng.random() < 0.2:
            line.append(_rand_choice(rng, [";", ",", ":"]))
        payload_lines.append(''.join(line))
    # Mix line endings
    newline = _rand_choice(rng, ["\n", "\r\n", "\r"])
    payload = newline.join(payload_lines)
    if len(payload) > 2048:
        payload = payload[:2048]

    # Build fields in an order that typical FUZZ_PARAM-consuming harnesses can use:
    # [filename1, search1, filename2, search2, filename3, search3, payload]
    fields: List[bytes] = []
    for i in range(3):
        fields.append(filenames[i].encode('utf-8', errors='ignore'))
        fields.append(search_strings[i].encode('utf-8', errors='ignore'))
    fields.append(payload.encode('utf-8', errors='ignore'))

    buf = _assemble_buffer(fields)

    # Ensure overall cap <= 4096 bytes
    return buf[:4096]
